let downX=0,downY=0
function interaction(){stopTour();tween=null;lastInteraction=performance.now()}
function remember(e:PointerEvent){downX=e.clientX;downY=e.clientY;interaction()}
function pick(e:PointerEvent){if(walking.value||props.overlayOpen)return;if(Math.hypot(e.clientX-downX,e.clientY-downY)>5)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(surfaces.filter(o=>o.visible))[0],cart=transportScene?.hitTest(ray);if(cart!==undefined&&(!hit||cart<hit.distance)){emit('transport');return}emit('select',hit?.object.userData.id||null)}
function move(to:THREE.Vector3,target:THREE.Vector3){if(!camera||!controls)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){camera.position.copy(to);controls.target.copy(target)}else tween={start:performance.now(),from:camera.position.clone(),to,fromTarget:controls.target.clone(),target};lastInteraction=performance.now()}
function toggleTransportFollow(){if(followTransport.value){resetView();return}if(!transportState.value||!controls)return;stopTour();if(walking.value)leaveWalk(false);followTransport.value=true;controls.minDistance=2.4;const p=transportPosition(),ground=imageToGround(p.x,p.y),target=new THREE.Vector3(ground[0],.7,ground[1]);move(target.clone().add(new THREE.Vector3(4,2.2,4)),target);lastInteraction=performance.now()}
function resetView(){followTransport.value=false;if(controls)controls.minDistance=18;stopTour();if(walking.value)leaveWalk(false);move(homePosition.clone(),homeTarget.clone())}
function zoomBy(factor:number){stopTour();if(walking.value)return;if(!camera||!controls)return;const offset=camera.position.clone().sub(controls.target).multiplyScalar(factor);if(offset.length()>=controls.minDistance&&offset.length()<=controls.maxDistance)move(controls.target.clone().add(offset),controls.target.clone())}
