function effectiveQuality(){return quality.value==='auto'?(innerWidth<=700?'low':'balanced'):quality.value}
function applyQuality(){if(!renderer||!sunlight)return;const mode=effectiveQuality(),size=mode==='high'?2048:1024;renderer.setPixelRatio(Math.min(devicePixelRatio,mode==='high'?1.5:mode==='balanced'?1.2:.85));renderer.shadowMap.enabled=mode!=='low';sunlight.castShadow=mode!=='low';if(sunlight.shadow.mapSize.x!==size){sunlight.shadow.map?.dispose();sunlight.shadow.map=null;sunlight.shadow.mapSize.set(size,size)}gardenFine.forEach(o=>o.visible=mode!=='low');if(host.value)renderer.setSize(host.value.clientWidth,host.value.clientHeight);lastInteraction=performance.now();try{localStorage.setItem('ty_orchard_quality',quality.value)}catch{}}
