function canStand(x:number,z:number){return !gardenWater.some(polygon=>inside([x,z],polygon))&&canNavigate(x,z,siteBoundary,waterBoundary,obstacles,treeObstacles,bridges)}
function enterWalk(startAt?:THREE.Vector3){
  if(props.overlayOpen||failure.value||!controls)return
