  let point:GroundPoint=startAt?[startAt.x,startAt.z]:imageToGround(370,343);if(startAt&&!canStand(...point)){let found=false;for(let radius=.8;radius<=8&&!found;radius+=.8)for(let i=0;i<24;i++){const angle=i*Math.PI/12,p:GroundPoint=[startAt.x+Math.sin(angle)*radius,startAt.z+Math.cos(angle)*radius];if(canStand(...p)){point=p;found=true;break}}}
