  const elevation=bridges.map(bridge=>bridgeHeight(...point,bridge)).find(height=>height!==null)??.17;camera.position.set(point[0],1.8+elevation,point[1]);yaw=Math.atan2(homeTarget.x-point[0],homeTarget.z-point[1]);walking.value=true;walkPaused.value=false;held.clear();controls.enabled=false;emit('walk',true);updateWalk(0)
}
function leaveWalk(restore=true){held.clear();walking.value=false;walkPaused.value=false;controls.enabled=true;emit('walk',false);if(restore)move(savedCamera.clone(),savedTarget.clone());lastInteraction=performance.now()}
function pauseWalk(){held.clear();if(walking.value)walkPaused.value=true}
function resumeWalk(){if(props.overlayOpen||document.hidden)return;held.clear();walkPaused.value=false;lastTick=performance.now()}
function visibilityChanged(){if(document.hidden){stopTour();pauseWalk()}}
function updateWalk(delta:number){
  if(walkPaused.value||props.overlayOpen)return
  const rotation=(held.has('arrowleft')?1:0)-(held.has('arrowright')?1:0);yaw+=rotation*delta*1.5
  const forward=(held.has('w')||held.has('arrowup')?1:0)-(held.has('s')||held.has('arrowdown')?1:0),strafe=(held.has('d')?1:0)-(held.has('a')?1:0),length=Math.hypot(forward,strafe)||1,speed=held.has('shift')?7:3.5
  const dx=(Math.sin(yaw)*forward-Math.cos(yaw)*strafe)*speed*delta/length,dz=(Math.cos(yaw)*forward+Math.sin(yaw)*strafe)*speed*delta/length
  if(canStand(camera.position.x+dx,camera.position.z))camera.position.x+=dx
  if(canStand(camera.position.x,camera.position.z+dz))camera.position.z+=dz
  const surfaceHeight=bridges.map(bridge=>bridgeHeight(camera.position.x,camera.position.z,bridge)).find(height=>height!==null)??.17;camera.position.y=THREE.MathUtils.lerp(camera.position.y,surfaceHeight+1.8,Math.min(1,delta*10));camera.lookAt(camera.position.x+Math.sin(yaw)*10,camera.position.y,camera.position.z+Math.cos(yaw)*10)
  orientation.value=Math.round((THREE.MathUtils.radToDeg(yaw)%360+360)%360);if(forward||strafe||rotation)lastInteraction=performance.now()
}
function keyDown(e:KeyboardEvent){
  if(!walking.value||props.overlayOpen||e.target instanceof HTMLElement&&e.target.closest('input,textarea,select,[contenteditable=true]'))return
  const key=e.key.toLowerCase();if(key==='escape'){e.preventDefault();leaveWalk();return}
  const modules:BusinessModule[]=['overview','monitoring','environment','devices','irrigation','crops','alerts'];if(/^[1-7]$/.test(key)){e.preventDefault();emit('module',modules[Number(key)-1]);return}
  if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','shift'].includes(key)){e.preventDefault();if(!walkPaused.value)held.add(key)}
}
function keyUp(e:KeyboardEvent){held.delete(e.key.toLowerCase())}
function touchStart(e:PointerEvent,key:string){if(walkPaused.value||props.overlayOpen)return;e.preventDefault();(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);held.add(key)}
function touchEnd(key:string){held.delete(key)}
function updateLabels(){
 if(transportState.value){const position=transportPosition(),ground=imageToGround(position.x,position.y),p=new THREE.Vector3(ground[0],1.75,ground[1]).project(camera);transportLabel.value={x:(p.x+1)*50,y:(1-p.y)*50,visible:showLabels.value&&!walking.value&&p.z>-1&&p.z<1&&Math.abs(p.x)<.96&&Math.abs(p.y)<.96}}else transportLabel.value.visible=false

  if(!host.value)return
  miniPosition.value={x:(camera.position.x-mapExtent.minX)/(mapExtent.maxX-mapExtent.minX)*160+10,y:(camera.position.z-mapExtent.minZ)/(mapExtent.maxZ-mapExtent.minZ)*90+10};const width=host.value.clientWidth,height=host.value.clientHeight,occupied:{x:number;y:number;w:number;h:number}[]=[]
  const hostRect=host.value.getBoundingClientRect();for(const element of Array.from(host.value.closest('.workspace')?.querySelectorAll('.weather,.scene-navigation,.scene-minimap,.walk-touch,.agriculture-panel,.drawer,.dock,.view-switch,.toolbar')||[])){const style=getComputedStyle(element);if(style.display==='none'||Number(style.opacity)<.1)continue;const r=element.getBoundingClientRect();occupied.push({x:r.left-hostRect.left+r.width/2,y:r.top-hostRect.top+r.height/2,w:r.width,h:r.height})}
  const uiReserved=occupied.length
  const candidates=sceneEntities.filter(e=>centers.has(e.id)&&(e.type!=='camera'||props.layers?.cameras===true)&&(e.id!=='yt-valve'||props.layers?.irrigation===true)).slice().sort((a,b)=>Number(b.id===props.selectedId)-Number(a.id===props.selectedId)||Number(b.type==='field')-Number(a.type==='field'))
  labels.value=candidates.map(e=>{
    const point=centers.get(e.id)!.clone().add(new THREE.Vector3(0,['field','greenhouse'].includes(e.type)?5:8,0)),p=point.clone().project(camera),x=(p.x+1)*width/2,y=(1-p.y)*height/2,w=Math.max(80,e.name.length*11+22),h=(visionCountsFor(e.id)?52:32)+(e.id===props.selectedId?(e.id.startsWith('yt-pear')?52:26):0)
    const layer=['field','greenhouse'].includes(e.type)?props.layers?.zones!==false:e.type==='camera'?props.layers?.cameras===true:props.layers?.devices!==false
    let visible=showLabels.value&&layer&&p.z>-1&&p.z<1&&x>w/2+8&&x<width-w/2-8&&y>90&&y<height-105
    if(visible&&walking.value){const direction=point.clone().sub(camera.position),ray=new THREE.Raycaster(camera.position,direction.clone().normalize(),.3,direction.length()-.7);if(ray.intersectObjects(occluders.filter(o=>o.visible),false).length)visible=false}
    if(visible&&occupied.some((r,index)=>(index<uiReserved||e.id!==props.selectedId)&&Math.abs(r.x-x)<(r.w+w)/2+5&&Math.abs(r.y-y)<(r.h+h)/2+5))visible=false
    if(visible)occupied.push({x,y,w,h})
    return {id:e.id,name:e.name,x:x/width*100,y:y/height*100,visible,pear:e.id.startsWith('yt-pear'),alert:props.layers?.alerts!==false&&e.status!=='normal'}
  })
}
function visionCountsFor(id:string){return props.visionCounts?.[id]||0}
defineExpose({resetView,zoomBy,focusEntity,getDiagnostics:()=>({calls:renderer?.info.render.calls,triangles:renderer?.info.render.triangles,geometries:renderer?.info.memory.geometries,textures:renderer?.info.memory.textures})});watch(()=>props.selectedId,highlight);onMounted(init)
onBeforeUnmount(()=>{held.clear();emit('walk',false);window.removeEventListener('keydown',keyDown);window.removeEventListener('keyup',keyUp);window.removeEventListener('blur',pauseWalk);document.removeEventListener('visibilitychange',visibilityChanged);cancelAnimationFrame(frame);transportScene?.dispose();observer?.disconnect();controls?.dispose();if(renderer){renderer.domElement.removeEventListener('pointerdown',remember);renderer.domElement.removeEventListener('pointerup',pick)}scene?.traverse(o=>{if(o instanceof THREE.Mesh||o instanceof THREE.Line){o.geometry.dispose();for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose()}});for(const texture of [...(modelMaterials?.textures||[]),...extraTextures])texture.dispose();renderer?.dispose()})
