<template><div class="orchard-three"><div ref="host" class="canvas-host"/><div class="three-labels"><div v-if="transportLabel.visible&&!followTransport" class="three-marker transport-marker" :style="{left:transportLabel.x+'%',top:transportLabel.y+'%'}"><button @click="toggleTransportFollow">运输车 01<small>点击跟随</small></button><button class="vision-link" @click="emit('transport')">导航控制 ↗</button></div><div v-for="label in labels.filter(l=>l.visible)" :key="label.id" class="three-marker" :style="{left:label.x+'%',top:label.y+'%'}"><button :class="{selected:selectedId===label.id,warning:label.alert}" @click="emit('select',label.id)" @dblclick="focusEntity(label.id)">{{ label.name }}<small v-if="visionCounts?.[label.id]">{{ visionCounts[label.id] }} 份视觉记录</small></button><button v-if="selectedId===label.id&&!walking" class="vision-link" @click="stopTour();focusEntity(label.id)">定位近景 ↗</button><button v-if="label.pear&&selectedId===label.id" class="vision-link" @click="emit('vision',label.id)">查看梨叶视觉 ↗</button></div></div><div class="scene-navigation"><div class="scene-navigation-heading"><span class="live-dot"/>果园植物园<small>园景示意</small></div><div class="scene-navigation-actions" v-if="!walking"><button @click="toggleTour" :disabled="overlayOpen" :aria-pressed="touring">{{ touring?'停止巡场':'自动巡场' }}</button><button @click="resetView">全景</button><button v-if="transportState" :aria-pressed="followTransport" @click="toggleTransportFollow">{{followTransport?'退出车辆跟随':'跟随运输车'}}</button><button @click="zoomBy(.8)" aria-label="3D 放大">＋</button><button @click="zoomBy(1.2)" aria-label="3D 缩小">－</button></div><button v-if="transportState" class="transport-launch" :disabled="overlayOpen" @click="emit('transport')"><span>运输导航 ↗</span><small>{{transportState.emergency?'已急停':taskStatus[transportState.tasks.find(t=>!['COMPLETED','CANCELLED'].includes(t.status))?.status||'']||'车辆空闲'}}</small></button><div v-if="touring" class="tour-status">正在巡场 · {{ tourName }}<span>{{ tourIndex }} / {{ farmZones.length }}</span></div><label class="scene-quality">画面质量<select v-model="quality" aria-label="3D 画面质量"><option value="auto">自动适配</option><option value="high">精细</option><option value="balanced">均衡</option><option value="low">流畅</option></select></label><div class="explore-actions"><button v-if="!walking" @click="enterWalk()" :disabled="overlayOpen">地面漫游</button><button v-else @click="leaveWalk()">退出漫游</button><button @click="showLabels=!showLabels" :aria-pressed="showLabels">{{ showLabels?'隐藏标注':'显示标注' }}</button></div><div v-if="walking" class="walk-state">{{ walkPaused?'漫游已暂停':'地面视角 · 方位 '+orientation+'°' }}<button v-if="walkPaused" @click="resumeWalk" :disabled="overlayOpen">继续漫游</button><small>WASD 移动 · ← → 转向 · Esc 退出</small></div><details v-if="!walking&&gardenSpots.length" class="garden-destinations"><summary>园景导览</summary><button v-for="spot in gardenSpots" :key="spot.name" @click="focusGarden(spot.point)" :disabled="overlayOpen">{{ spot.name }}</button><button v-if="activeGardenStart" @click="enterWalk(activeGardenStart || undefined)" :disabled="overlayOpen">从此处漫游</button></details><details v-if="!walking"><summary>定位地块</summary><button v-for="zone in farmZones" :key="zone.entityId" @click="stopTour();focusEntity(zone.entityId)">{{ sceneEntities.find(e=>e.id===zone.entityId)?.name }}</button></details></div><aside v-if="walking" class="scene-minimap" aria-label="漫游位置图"><span>基地平面 · 位置示意</span><svg viewBox="0 0 180 110"><polygon v-for="plot in miniPlots" :key="plot.id" :points="plot.points" :class="{active:selectedId===plot.id}"><title>{{ plot.name }}</title></polygon><circle class="walker-position" :cx="miniPosition.x" :cy="miniPosition.y" r="3"/><path :transform="`translate(${miniPosition.x} ${miniPosition.y}) rotate(${-orientation})`" d="M0 1 L-5 10 L5 10 Z"/></svg></aside><div v-if="walking&&!walkPaused&&!overlayOpen" class="walk-touch"><button v-for="key in ['arrowleft','w','arrowright','a','s','d']" :key="key" :aria-label="'漫游 '+key" @pointerdown="touchStart($event,key)" @pointerup="touchEnd(key)" @pointercancel="touchEnd(key)" @lostpointercapture="touchEnd(key)">{{ ({arrowleft:'↶',w:'↑',arrowright:'↷',a:'←',s:'↓',d:'→'} as Record<string,string>)[key] }}</button></div><p class="three-help">{{ failure||walkNotice||'拖动旋转 · 滚轮缩放 · 双击聚焦｜地块沿二维边界建模，概念坐标未经 GIS 校准' }}</p></div></template>
